CREATE TABLE IF NOT EXISTS community_engagement_plans (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), asset_id uuid NOT NULL REFERENCES continental_assets(id) ON DELETE CASCADE, plan_version integer NOT NULL DEFAULT 1, engagement_status text NOT NULL DEFAULT 'Draft', participation_standard text NOT NULL DEFAULT 'Inclusive, documented and evidence-based', affected_communities_summary text, stakeholder_mapping_status text NOT NULL DEFAULT 'Pending', disclosure_status text NOT NULL DEFAULT 'Pending', consultation_status text NOT NULL DEFAULT 'Pending', consent_status text NOT NULL DEFAULT 'Not Assessed', grievance_status text NOT NULL DEFAULT 'Open', benefit_sharing_status text NOT NULL DEFAULT 'Not Assessed', investment_gate text NOT NULL DEFAULT 'Blocked', rationale text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(asset_id,plan_version));
CREATE TABLE IF NOT EXISTS community_stakeholders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), plan_id uuid NOT NULL REFERENCES community_engagement_plans(id) ON DELETE CASCADE, stakeholder_type text NOT NULL, stakeholder_name text, representation_basis text, customary_or_statutory_role text, contact_reference text, affected_interest text, participation_status text NOT NULL DEFAULT 'Identified', sensitive boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS community_engagement_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), plan_id uuid NOT NULL REFERENCES community_engagement_plans(id) ON DELETE CASCADE, event_type text NOT NULL, event_date timestamptz, location_summary text, notice_method text, disclosure_material_reference text, participants_summary text, questions_summary text, objections_summary text, commitments_summary text, minutes_reference text, evidence_reference text, facilitator_reference text, status text NOT NULL DEFAULT 'Recorded', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS community_positions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), plan_id uuid NOT NULL REFERENCES community_engagement_plans(id) ON DELETE CASCADE, stakeholder_id uuid REFERENCES community_stakeholders(id) ON DELETE SET NULL, position_type text NOT NULL, position_status text NOT NULL DEFAULT 'Recorded', conditions text, rationale text, evidence_reference text, recorded_at timestamptz NOT NULL DEFAULT now(), reviewer_reference text, status text NOT NULL DEFAULT 'Active');
CREATE TABLE IF NOT EXISTS community_benefit_proposals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), plan_id uuid NOT NULL REFERENCES community_engagement_plans(id) ON DELETE CASCADE, proposal_type text NOT NULL, description text NOT NULL, beneficiary_basis text, measurement_method text, proposed_value text, community_response text, approval_status text NOT NULL DEFAULT 'Proposed', evidence_reference text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS community_participation_decisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), plan_id uuid NOT NULL REFERENCES community_engagement_plans(id) ON DELETE CASCADE, decision_type text NOT NULL, decision text NOT NULL, rationale text NOT NULL, blocking boolean NOT NULL DEFAULT false, conditions text, decision_authority_reference text, evidence_reference text, decided_at timestamptz NOT NULL DEFAULT now(), status text NOT NULL DEFAULT 'Recorded');
CREATE INDEX IF NOT EXISTS idx_engagement_asset ON community_engagement_plans(asset_id,plan_version DESC);
CREATE INDEX IF NOT EXISTS idx_stakeholders_plan ON community_stakeholders(plan_id);
CREATE INDEX IF NOT EXISTS idx_engagement_events_plan ON community_engagement_events(plan_id,event_date DESC);
CREATE INDEX IF NOT EXISTS idx_community_positions_plan ON community_positions(plan_id,recorded_at DESC);
CREATE INDEX IF NOT EXISTS idx_participation_decisions_plan ON community_participation_decisions(plan_id,decided_at DESC);